    var buffer: [128]u8 = undefined;
    const response = try responseFor("GET", "/unknown", &count, &buffer);

    try std.testing.expectEqualStrings("404 Not Found", response.status);
    try std.testing.expectEqual(@as(u64, 0), count);
}

